import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  computed,
  signal,
  forwardRef,
  inject,
  InjectionToken,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { cn } from '../lib/utils';

export const RADIO_GROUP = new InjectionToken<RadioGroupComponent>('RADIO_GROUP');

@Component({
  selector: 'ui-radio-group-item',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (label()) {
      <div class="flex items-center gap-2">
        <button
          type="button"
          role="radio"
          [attr.aria-checked]="isSelected()"
          [attr.data-state]="isSelected() ? 'checked' : 'unchecked'"
          [class]="classes()"
          [disabled]="isDisabled()"
          [attr.id]="computedId()"
          [attr.data-slot]="'radio-group-item'"
          (click)="select()"
        >
          @if (isSelected()) {
            <span class="flex items-center justify-center">
              <span class="h-2.5 w-2.5 rounded-full bg-current"></span>
            </span>
          }
        </button>
        <label 
          [attr.for]="computedId()" 
          class="text-sm font-medium leading-none cursor-pointer peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
          (click)="select(); $event.preventDefault()"
        >
          {{ label() }}
        </label>
      </div>
    } @else {
      <button
        type="button"
        role="radio"
        [attr.aria-checked]="isSelected()"
        [attr.data-state]="isSelected() ? 'checked' : 'unchecked'"
        [class]="classes()"
        [disabled]="isDisabled()"
        [attr.aria-label]="ariaLabel()"
        [attr.data-slot]="'radio-group-item'"
        (click)="select()"
      >
        @if (isSelected()) {
          <span class="flex items-center justify-center">
            <span class="h-2.5 w-2.5 rounded-full bg-current"></span>
          </span>
        }
      </button>
    }
  `,
  host: {
    '[class]': '"contents"',
  },
})
export class RadioGroupItemComponent {
  private static idCounter = 0;

  value = input.required<string>();
  disabled = input(false);
  class = input('');
  ariaLabel = input<string | undefined>(undefined);

  // Simple mode: inline label
  label = input<string | undefined>(undefined);

  // Auto-generate ID when label is used
  private _generatedId = `radio-${++RadioGroupItemComponent.idCounter}`;
  computedId = computed(() => this._generatedId);

  private group = inject(RADIO_GROUP, { optional: true });

  isSelected = computed(() => this.group?.value() === this.value());
  isDisabled = computed(() => this.disabled() || (this.group?.isDisabled() ?? false));

  classes = computed(() =>
    cn(
      'aspect-square h-4 w-4 rounded-full border border-primary text-primary shadow focus:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 flex items-center justify-center',
      this.isSelected() ? 'border-primary' : 'bg-background',
      this.class()
    )
  );

  select() {
    if (this.isDisabled() || !this.group) return;
    this.group.selectValue(this.value());
  }
}

@Component({
  selector: 'ui-radio-group',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [RadioGroupItemComponent],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => RadioGroupComponent),
      multi: true,
    },
    {
      provide: RADIO_GROUP,
      useExisting: RadioGroupComponent,
    },
  ],
  template: `
    <div
      role="radiogroup"
      [attr.aria-orientation]="orientation()"
      [class]="classes()"
      [attr.data-slot]="'radio-group'"
    >
      @if (isDataDriven()) {
        @for (option of options(); track $index) {
           <ui-radio-group-item 
              [value]="getValue(option)" 
              [label]="getDisplayValue(option)" 
              [disabled]="isOptionDisabled(option)" 
           />
        }
      } @else {
        <ng-content />
      }
    </div>
  `,
  host: {
    '[class]': '"contents"',
  },
})
export class RadioGroupComponent<T = unknown> implements ControlValueAccessor {
  orientation = input<'horizontal' | 'vertical'>('vertical');
  disabled = input(false);
  class = input('');

  // Data-driven inputs
  readonly options = input<T[]>([]);
  readonly displayWith = input<(option: T) => string>((opt) => String(opt));
  readonly valueAttribute = input<string | undefined>(undefined);
  readonly disabledWith = input<(option: T) => boolean>(() => false);

  private formDisabled = signal(false);
  isDisabled = computed(() => this.disabled() || this.formDisabled());
  readonly isDataDriven = computed(() => this.options().length > 0);

  value = signal<string | null>(null);
  valueChange = output<string>();

  private onChange: (value: string) => void = () => { };
  private onTouched: () => void = () => { };

  classes = computed(() =>
    cn(
      'grid gap-2',
      this.orientation() === 'horizontal' ? 'grid-flow-col' : 'grid-flow-row',
      this.class()
    )
  );

  getDisplayValue(option: T): string {
    return this.displayWith()(option);
  }

  getValue(option: T): string {
    if (this.valueAttribute()) {
      return String((option as Record<string, unknown>)[this.valueAttribute()!]);
    }
    return String(option);
  }

  isOptionDisabled(option: T): boolean {
    return this.disabledWith()(option);
  }

  selectValue(val: string) {
    if (this.isDisabled()) return;
    this.value.set(val);
    this.onChange(val);
    this.valueChange.emit(val);
    this.onTouched();
  }

  writeValue(value: string): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.formDisabled.set(isDisabled);
  }
}
