import {
  Component,
  ChangeDetectionStrategy,
  input,
  computed,
  signal,
  inject,
  InjectionToken,
  forwardRef,
} from '@angular/core';
import { cn } from '../lib/utils';

export const ACCORDION = new InjectionToken<AccordionComponent>('ACCORDION');

let accordionIdCounter = 0;

@Component({
  selector: 'ui-accordion',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [{ provide: ACCORDION, useExisting: forwardRef(() => AccordionComponent) }],
  template: `
    <div [class]="classes()" [attr.data-slot]="'accordion'">
      <ng-content />
    </div>
  `,
  host: { '[class]': '"contents"' },
})
export class AccordionComponent {
  type = input<'single' | 'multiple'>('single');
  class = input('');

  readonly accordionId = `accordion-${++accordionIdCounter}`;
  openItems = signal<Set<string>>(new Set());

  classes = computed(() => cn('w-full', this.class()));

  toggle(value: string) {
    const current = this.openItems();
    if (this.type() === 'single') {
      if (current.has(value)) {
        this.openItems.set(new Set());
      } else {
        this.openItems.set(new Set([value]));
      }
    } else {
      const next = new Set(current);
      if (next.has(value)) {
        next.delete(value);
      } else {
        next.add(value);
      }
      this.openItems.set(next);
    }
  }

  isOpen(value: string): boolean {
    return this.openItems().has(value);
  }

  getTriggerId(value: string): string {
    return `${this.accordionId}-trigger-${value}`;
  }

  getPanelId(value: string): string {
    return `${this.accordionId}-panel-${value}`;
  }
}

export const ACCORDION_ITEM = new InjectionToken<AccordionItemComponent>('ACCORDION_ITEM');

@Component({
  selector: 'ui-accordion-item',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [{ provide: ACCORDION_ITEM, useExisting: forwardRef(() => AccordionItemComponent) }],
  template: `
    <div [class]="classes()" [attr.data-slot]="'accordion-item'">
      @if (title()) {
        <!-- Simple mode: render built-in trigger and content -->
        <h3 class="flex">
          <button
            type="button"
            [attr.id]="triggerId()"
            class="flex flex-1 items-center justify-between py-4 text-sm font-medium transition-all hover:underline [&[data-state=open]>svg]:rotate-180"
            [attr.aria-expanded]="isOpen()"
            [attr.aria-controls]="panelId()"
            [attr.data-state]="isOpen() ? 'open' : 'closed'"
            [attr.data-slot]="'accordion-trigger'"
            (click)="toggle()"
          >
            {{ title() }}
            <svg
              class="h-4 w-4 shrink-0 text-muted-foreground transition-transform duration-200"
              [class.rotate-180]="isOpen()"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              stroke-width="2"
            >
              <path stroke-linecap="round" stroke-linejoin="round" d="M19 9l-7 7-7-7" />
            </svg>
          </button>
        </h3>
        @if (isOpen()) {
          <div
            role="region"
            [attr.id]="panelId()"
            [attr.aria-labelledby]="triggerId()"
            class="overflow-hidden text-sm"
            [attr.data-state]="'open'"
            [attr.data-slot]="'accordion-content'"
          >
            <div class="pb-4 pt-0">{{ content() }}</div>
          </div>
        }
      } @else {
        <!-- Custom mode: render projected content -->
        <ng-content />
      }
    </div>
  `,
  host: { '[class]': '"contents"' },
})
export class AccordionItemComponent {
  value = input.required<string>();
  class = input('');

  // Simple mode: title and content inputs
  title = input<string | undefined>(undefined);
  content = input<string | undefined>(undefined);

  private accordion = inject(ACCORDION, { optional: true });

  isOpen = computed(() => {
    return this.accordion?.isOpen(this.value()) ?? false;
  });

  triggerId = computed(() => {
    return this.accordion?.getTriggerId(this.value()) ?? '';
  });

  panelId = computed(() => {
    return this.accordion?.getPanelId(this.value()) ?? '';
  });

  toggle() {
    this.accordion?.toggle(this.value());
  }

  classes = computed(() => cn('border-b', this.class()));
}

@Component({
  selector: 'ui-accordion-trigger',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <h3 class="flex">
      <button
        type="button"
        [attr.id]="triggerId()"
        [class]="classes()"
        [attr.aria-expanded]="isOpen()"
        [attr.aria-controls]="panelId()"
        [attr.data-state]="isOpen() ? 'open' : 'closed'"
        [attr.data-slot]="'accordion-trigger'"
        (click)="toggle()"
      >
        <ng-content />
        <svg
          class="h-4 w-4 shrink-0 text-muted-foreground transition-transform duration-200"
          [class.rotate-180]="isOpen()"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          stroke-width="2"
        >
          <path stroke-linecap="round" stroke-linejoin="round" d="M19 9l-7 7-7-7" />
        </svg>
      </button>
    </h3>
  `,
  host: { '[class]': '"contents"' },
})
export class AccordionTriggerComponent {
  class = input('');

  private accordion = inject(ACCORDION, { optional: true });
  private item = inject(AccordionItemComponent, { optional: true });

  isOpen = computed(() => {
    const val = this.item?.value();
    return val ? this.accordion?.isOpen(val) ?? false : false;
  });

  triggerId = computed(() => {
    const val = this.item?.value();
    return val ? this.accordion?.getTriggerId(val) ?? '' : '';
  });

  panelId = computed(() => {
    const val = this.item?.value();
    return val ? this.accordion?.getPanelId(val) ?? '' : '';
  });

  classes = computed(() =>
    cn(
      'flex flex-1 items-center justify-between py-4 text-sm font-medium transition-all hover:underline [&[data-state=open]>svg]:rotate-180',
      this.class()
    )
  );

  toggle() {
    const val = this.item?.value();
    if (val && this.accordion) {
      this.accordion.toggle(val);
    }
  }
}

@Component({
  selector: 'ui-accordion-content',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (isOpen()) {
      <div
        role="region"
        [attr.id]="panelId()"
        [attr.aria-labelledby]="triggerId()"
        [class]="classes()"
        [attr.data-state]="isOpen() ? 'open' : 'closed'"
        [attr.data-slot]="'accordion-content'"
      >
        <div class="pb-4 pt-0">
          <ng-content />
        </div>
      </div>
    }
  `,
  host: { '[class]': '"contents"' },
})
export class AccordionContentComponent {
  class = input('');

  private accordion = inject(ACCORDION, { optional: true });
  private item = inject(AccordionItemComponent, { optional: true });

  isOpen = computed(() => {
    const val = this.item?.value();
    return val ? this.accordion?.isOpen(val) ?? false : false;
  });

  triggerId = computed(() => {
    const val = this.item?.value();
    return val ? this.accordion?.getTriggerId(val) ?? '' : '';
  });

  panelId = computed(() => {
    const val = this.item?.value();
    return val ? this.accordion?.getPanelId(val) ?? '' : '';
  });

  classes = computed(() =>
    cn('overflow-hidden text-sm', this.class())
  );
}

